#!/usr/bin/env bash
# Regenerate the committed sample outputs and traces.
#
# Everything under output_examples/ and logs/samples/ is generated by this script and by the runs
# it starts. Never edit those files by hand: if the code changes, re-run this and let the diff
# show exactly what changed.
set -euo pipefail

cd "$(dirname "$0")/.."
PY="${PY:-.venv/bin/python}"
mkdir -p output_examples logs/samples

for n in 1 2 3; do
  echo "=== example_$n ==="
  "$PY" run.py --input "input_examples/example_$n.json" \
    --scenario "data/scenarios/example_$n" \
    --out "output_examples/example_$n.json" > "output_examples/example_$n.log"

  # Which trace, state and report belong to this run is a fact the run already recorded, so read it
  # from the report instead of guessing "the newest file". Two runs land in the same second, and an
  # mtime tie silently copies the *previous* scenario's trace into the evidence: the committed
  # traces were one scenario behind until this was fixed. `tests/test_evidence.py` now asserts that
  # every committed trace carries its own report's run id and narrative.
  paths="$("$PY" - "$n" <<'PYEOF'
import json, pathlib, sys
report = json.loads(pathlib.Path(f"output_examples/example_{sys.argv[1]}.json").read_text())
trace = report["trace_path"]
print(trace.replace("trace-", "state-", 1), report["report_markdown_path"], trace)
PYEOF
)"
  read -r state report trace <<< "$paths"
  cp "$trace"  "logs/samples/trace-example_$n.jsonl"
  cp "$state"  "logs/samples/state-example_$n.jsonl"
  cp "$report" "output_examples/example_${n}_report.md"
  echo "trace:  logs/samples/trace-example_$n.jsonl ($(wc -l < "$trace" | tr -d ' ') lines)"
done

# Use an explicit caller scratch directory; a clean setup defaults inside ignored logs.
export TMPDIR="${TMPDIR:-$PWD/logs/scratch}"
mkdir -p "$TMPDIR"
work="$(mktemp -d "${TMPDIR%/}/driftwatch-examples.XXXXXX")"
trap 'rm -rf "$work"' EXIT

echo
echo "=== evaluation ==="
# The evaluator's own nonzero status exits under set -e BEFORE filtering or publication.
"$PY" -m evals.run_eval > "$work/eval.stdout"
"$PY" - "$work/eval.stdout" output_examples/eval.txt <<'PYEOF'
from pathlib import Path
import sys
lines=Path(sys.argv[1]).read_text().splitlines(keepends=True)
selected="".join(line for line in lines if line.startswith(("example_", "  must-not-flag")) or "scenarios," in line)
Path(sys.argv[2]).write_text(selected)
print(selected,end="")
PYEOF

echo
echo "=== held-out scoring: tenancies generated from a seed, not written by hand ==="
"$PY" scripts/make_scenario.py --score 10 --out "$work/held-out" > "$work/held-out.stdout"
"$PY" - "$work/held-out.stdout" output_examples/held_out.txt <<'PYEOF'
from pathlib import Path
import sys
lines=Path(sys.argv[1]).read_text().splitlines(keepends=True)
selected="".join(line for line in lines if line.startswith("held_out") or "held-out tenancies," in line)
Path(sys.argv[2]).write_text(selected)
print(selected,end="")
PYEOF
